               '"" -> Err("пусто")\n'
               '"   \\n  " -> Err("пусто")\n'
               '"a\\n\\n\\n\\nb" -> Ok("a\\n\\nb")\n'
               '"tab\\there" -> Err("длинно")\n'
               '"ёёёёё" -> Ok("ёёёёё")\n'
               '"ёёёёёё" -> Err("длинно")\n'
