               'Члены комнаты: проверку членства делайте запросом (не-участнику 404).\n'
               '\n'
               'Ожидаемый вывод:\n'
               '200 '
               '{"items":[{"id":7,"text":"m7"},{"id":6,"text":"m6"},{"id":5,"text":"m5"}],"next_before":5}\n'
               '200 '
