 {'id': 'r49-typing',
  'mode': 'rust',
  'title': 'Индикатор «печатает…»',
  'statement': 'Реализуйте структуру Typing { ttl_ms } (хранит в памяти для каждой комнаты, кто и '
               'когда последний раз печатал): метод ping(&mut self, room: u32, user: &str, now_ms: '
               'u64) отмечает набор текста; who(&mut self, room: u32, now_ms: u64) -> Vec<String> '
               'возвращает имена тех, чей последний ping не старше ttl_ms (строго: now − t < ttl), '
               'по алфавиту; устаревшие записи при этом удаляются. Комнаты независимы; пустая '
               'комната вовсе исчезает из памяти (метод rooms_tracked() -> usize показывает число '
               'комнат с записями).\n'
               '\n'
               'Ожидаемый вывод:\n'
               '["anna", "vera"]\n'
               '["anna"]\n'
               '["anna"]\n'
               '[]\n'
               '1\n'
               '["anna"]\n'
               '["boris"] []\n'
               '1\n'
               '[]',
  'starter': 'use std::collections::HashMap;\n'
             '\n'
             'struct Typing {\n'
             '    ttl_ms: u64,\n'
             '    rooms: HashMap<u32, HashMap<String, u64>>,\n'
             '}\n'
             '\n'
             'impl Typing {\n'
             '    fn new(ttl_ms: u64) -> Typing {\n'
             '        Typing { ttl_ms, rooms: HashMap::new() }\n'
             '    }\n'
             '    fn ping(&mut self, room: u32, user: &str, now_ms: u64) {\n'
             '        todo!()\n'
             '    }\n'
             '    fn who(&mut self, room: u32, now_ms: u64) -> Vec<String> {\n'
             '        todo!()\n'
             '    }\n'
             '    fn rooms_tracked(&self) -> usize {\n'
             '        self.rooms.len()\n'
             '    }\n'
             '}\n'
             '\n'
             'fn main() {\n'
             '    let mut t = Typing::new(3000);\n'
             '    t.ping(1, "vera", 0);\n'
             '    t.ping(1, "anna", 1000);\n'
             '    t.ping(2, "boris", 1500);\n'
             '    println!("{:?}", t.who(1, 2000));\n'
             '    println!("{:?}", t.who(1, 3000));\n'
             '    println!("{:?}", t.who(1, 3999));\n'
             '    println!("{:?}", t.who(1, 4000));\n'
             '    println!("{}", t.rooms_tracked());\n'
             '    t.ping(1, "anna", 5000);\n'
             '    t.ping(1, "anna", 6000);\n'
             '    println!("{:?}", t.who(1, 8999));\n'
             '    println!("{:?} {:?}", t.who(2, 4499), t.who(2, 4500));\n'
             '    println!("{}", t.rooms_tracked());\n'
             '    println!("{:?}", t.who(9, 0));\n'
             '}\n',
  'driver': '',
  'hint': 'HashMap<u32, HashMap<String, u64>>; retain; remove пустых комнат.',
  'standalone': True,
  'crates': ['tokio'],
  'expected': ['["anna", "vera"]',
               '["anna"]',
               '["anna"]',
               '[]',
               '1',
               '["anna"]',
               '["boris"] []',
               '1',
               '[]']},
